const {
  DEFAULT_TIMEOUT_MS,
  DEFAULT_RATE_LIMIT_RPM,
  DEFAULT_MAX_RETRIES,
  configureRateLimit,
  buildHeaders,
  normalizeBaseUrl,
  fetchJson,
  parseTotalHeader,
} = require('../lib/wp-http.js');
const {
  classifyRoutes,
  summarizeSkippedByCategory,
  buildRegisteredRestBases,
  defaultPluginRules,
  defaultQueryFor,
  defaultQueryReasonFor,
} = require('../lib/wp-route-classifier.js');
// Plugin awareness: detection runs before classification so profile routes are
// in scope; embedded detection and Tier-B derivation run after sampling because they need
// real record payloads and the accepted route set.
const { gatherInventory, inventoryPayload } = require('./wp-plugin-inventory.js');
const {
  pluginsRoot,
  loadProfiles,
  loadNoMigrationNeeded,
  loadRequiresDevelopment,
  loadPendingDecisions,
  loadFingerprintAliases,
  CHILD_ROUTE_PLACEHOLDER,
  buildResponseEnvelopes,
  buildRequestOverrides,
  buildResponseFragmentGroups,
  buildRecordKeyFields,
} = require('../lib/plugin-knowledge.js');
const {
  buildDispositionRows,
  summarizeDispositions,
} = require('../lib/plugin-disposition.js');
const {
  detectPlugins,
  collectRecordProperties,
  collectUnprofiledRoutes,
  collectCandidateNamespaces,
  deriveGenericEntities,
  classifyCoverage,
  coverageSummary,
} = require('../lib/wp-plugin-detect.js');
const {
  collectAllIds,
  queryInBatches,
  DEFAULT_BATCH_SIZE,
} = require('../lib/sampled-ids-batch.js');

const DEFAULT_SAMPLE_LIMIT = 3;
let progress;

